export function expandKey(keyBytes) {
  const keyLength = keyBytes.length;
  const nk = keyLength / 4;
  const nr = nk + 6;
  const wordCount = 4 * (nr + 1);
  const words = new Array(wordCount);

  for (let index = 0; index < nk; index += 1) {
    const offset = index * 4;
    words[index] = [
      keyBytes[offset],
      keyBytes[offset + 1],
      keyBytes[offset + 2],
      keyBytes[offset + 3],
    ];
  }

  for (let index = nk; index < wordCount; index += 1) {
    let temp = words[index - 1].slice();

    if (index % nk === 0) {
      temp = subWord(rotWord(temp));
      temp[0] ^= RCON[index / nk];
    } else if (nk > 6 && index % nk === 4) {
      temp = subWord(temp);
    }

    words[index] = xorWords(words[index - nk], temp);
  }

  const roundKeys = new Uint8Array(wordCount * 4);

  for (let index = 0; index < words.length; index += 1) {
    roundKeys.set(words[index], index * 4);
  }

  return { nr, roundKeys };
